/* Calm, premium, dark: a quiet interview room (UX.md: look and feel). */

:root {
  /* Background */
  --bg: #0e1117;
  --bg-gradient:
    radial-gradient(1200px 700px at 15% -10%, #1e2a44 0%, transparent 60%),
    radial-gradient(900px 600px at 110% 20%, #23203d 0%, transparent 55%),
    linear-gradient(180deg, #10141c 0%, #0b0e13 100%);

  /* Glass: dark enough that text keeps AA contrast whatever is behind it. */
  --glass-bg: rgba(22, 27, 37, 0.72);
  --glass-border: rgba(255, 255, 255, 0.09);
  --glass-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
  --glass-blur: 18px;
  --solid-panel: #161b25;

  /* Plain surfaces inside glass */
  --surface: rgba(255, 255, 255, 0.04);
  --surface-hover: rgba(255, 255, 255, 0.07);
  --border: rgba(255, 255, 255, 0.1);

  /* Text */
  --text: #e9ecf2;
  --muted: #a3acbc;

  /* The one accent colour */
  --accent: #8fb4ff;
  --accent-text: #0d1320;
  --accent-soft: rgba(143, 180, 255, 0.14);

  /* Radius scale: the only radius values in the app */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-pill: 999px;

  --ease: 160ms ease;
  --sans: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;

  font: 17px/1.55 var(--sans);
  color-scheme: dark;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100svh;
  background: var(--bg-gradient);
  background-attachment: fixed;
}

/* Layout */

.app {
  min-height: 100svh;
  display: grid;
  grid-template-areas:
    'main'
    'footer';
  grid-template-rows: 1fr auto;
  gap: 24px;
  max-width: 880px;
  margin: 0 auto;
  padding: 32px 16px 16px;
}

main {
  grid-area: main;
  min-width: 0;
}

footer {
  grid-area: footer;
  padding: 0 4px;
}

/* Interview: the engine's stage sits beside the screen. */
.app--interview {
  max-width: 1120px;
  grid-template-areas:
    'stage main'
    'footer footer';
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  grid-template-rows: 1fr auto;
  align-items: start;
}

@media (max-width: 760px) {
  .app--interview {
    grid-template-areas:
      'stage'
      'main'
      'footer';
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
  }
}

.engine-host {
  grid-area: stage;
  min-width: 0;
}

.engine-host[hidden] {
  display: none;
}

/* Glass: only on the few big panels that carry the .glass class. */

.glass {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--glass-shadow);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(120%);
  backdrop-filter: blur(var(--glass-blur)) saturate(120%);
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .glass {
    background: var(--solid-panel);
  }
}

@media (prefers-reduced-transparency: reduce) {
  .glass {
    background: var(--solid-panel);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

.screen {
  padding: 28px 28px 24px;
  animation: screen-in var(--ease);
}

@keyframes screen-in {
  from {
    opacity: 0;
  }
}

/* Type */

h1 {
  font-size: 1.85rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0 0 12px;
}

h2,
legend {
  font-size: 1.05rem;
  font-weight: 600;
  margin: 0 0 6px;
  padding: 0;
}

h1:focus,
h2:focus {
  outline: none;
}

p {
  margin: 0 0 8px;
}

.lede {
  color: var(--muted);
  font-size: 1.08rem;
  margin-bottom: 24px;
}

.muted {
  color: var(--muted);
}

.placeholder {
  color: var(--muted);
  font-style: italic;
}

.privacy-note {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0;
}

/* Plain surfaces inside the glass panel: no blur. */

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px 18px;
  margin: 0 0 14px;
}

/* Controls */

button {
  font: inherit;
  font-weight: 500;
  border-radius: var(--radius-md);
  padding: 10px 18px;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  transition:
    background-color var(--ease),
    border-color var(--ease),
    opacity var(--ease);
}

button:hover {
  background: var(--surface-hover);
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}

button.primary:hover {
  opacity: 0.9;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

input[type='radio'] {
  accent-color: var(--accent);
  width: 18px;
  height: 18px;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
  margin-top: 18px;
}

/* Home: mode choice */

.mode-options {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  margin: 12px 0;
}

.mode-option {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  text-align: left;
  padding: 16px 18px;
}

.mode-option:hover:not(:disabled) {
  border-color: var(--accent);
}

/* Unavailable, but the reason inside must stay readable: no fading. */
.mode-option:disabled {
  opacity: 1;
  border-style: dashed;
  background: transparent;
}

.mode-option:disabled .mode-name {
  color: var(--muted);
}

/* A plain notice: neutral, no warning colour (one accent only). */
.notice {
  border-left: 3px solid var(--text);
  padding: 2px 0 2px 14px;
}

.notice-title {
  font-weight: 600;
}

.notice p:last-child {
  margin-bottom: 0;
}

.mode-name,
.choice-name {
  font-weight: 600;
  display: block;
}

.mode-detail,
.choice-detail {
  color: var(--muted);
  font-size: 0.95rem;
  display: block;
}

/* Setup: radio choices */

.choice-group {
  display: grid;
  gap: 6px;
  min-width: 0;
  border: 0;
  margin: 0 0 8px;
  padding: 0;
}

/* Keep the legend in the flow instead of on a border. */
.choice-group legend {
  float: left;
  width: 100%;
  margin-bottom: 6px;
}

.choice {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition:
    background-color var(--ease),
    border-color var(--ease);
}

.choice:hover {
  background: var(--surface-hover);
}

.choice:has(input:checked) {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.choice input {
  margin-top: 3px;
  flex: none;
}

/* Interview */

.stage {
  aspect-ratio: 3 / 4;
  background: var(--solid-panel);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--glass-shadow);
  display: grid;
  place-items: center;
  overflow: hidden;
}

.stage-phone {
  aspect-ratio: 1;
}

.state {
  display: inline-block;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: var(--radius-pill);
  padding: 3px 14px;
  margin-bottom: 12px;
}

.label {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin: 18px 0 4px;
}

.question {
  font-size: 1.25rem;
  line-height: 1.45;
}

.interview-controls {
  justify-content: flex-start;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

import type { Display, Mode } from './state'

// Everything a first visit downloads, with real sizes (UX.md: downloads).
// One list, so the home page, the setup progress (step 1.6) and the README
// agree. Sizes are decimal MB, as Hugging Face shows them, measured 3 Oct 2026:
// Hugging Face API file listings (model files plus their JSON/tokenizer), the
// jsDelivr metadata API for CDN files, and a minified build for the 3D code.

export type DownloadItem = {
  id: string
  job: string
  name: string
  bytes: number
  // Which modes and displays need it. Missing means all.
  modes?: Mode[]
  displays?: Display[]
}

const MB = 1e6

export const DOWNLOADS: DownloadItem[] = [
  // @ricky0123/vad-web@0.0.30 silero_vad_legacy.onnx (the package's default).
  { id: 'vad', job: 'Hears when you start and stop talking', name: 'Silero VAD', bytes: 1.8 * MB },
  // onnx-community/whisper-base, fp32 on WebGPU (transformers.js default):
  // encoder 82.5 + merged decoder 208.5 + tokenizer files.
  { id: 'whisper', job: 'Turns your speech into text', name: 'Whisper base', bytes: 295 * MB },
  // onnx-community/Kokoro-82M-v1.0-ONNX model.onnx (fp32) + one voice.
  { id: 'kokoro', job: "The interviewer's voice", name: 'Kokoro 82M', bytes: 326 * MB },
  // onnx-community/gemma-3-1b-it-ONNX model_q4 + tokenizer (20 MB).
  { id: 'gemma-light', job: 'The interviewer', name: 'Gemma 3 1B', bytes: 880 * MB, modes: ['light'] },
  // onnx-community/gemma-4-E2B-it-ONNX embed_tokens + decoder q4f16 (text
  // parts only) + tokenizer (19 MB).
  { id: 'gemma-heavy', job: 'The interviewer and reviewer', name: 'Gemma 4 E2B', bytes: 3130 * MB, modes: ['heavy'] },
  // ONNX Runtime WebAssembly: 14.0 MB for the voice detector, 25.8 MB shared
  // by the speech and voice workers, ~27 MB for the Gemma worker's own
  // runtime (transformers.js 4.3.0; confirmed at step 1.3).
  { id: 'runtime', job: 'Runs the models in the browser', name: 'ONNX Runtime', bytes: 67 * MB },
  // 3D code (three.js, the avatar component): +2.4 MB over the headless
  // build, plus one avatar model (Ananya 4.5 MB, Aarav 4.7 MB).
  { id: 'avatar', job: 'The interviewer on screen', name: '3D avatar', bytes: 7 * MB, displays: ['video'] },
]

export function downloadsFor(mode: Mode, display?: Display): DownloadItem[] {
  return DOWNLOADS.filter(
    (d) =>
      (!d.modes || d.modes.includes(mode)) &&
      (!d.displays || (display !== undefined && d.displays.includes(display))),
  )
}

export function totalBytes(items: DownloadItem[]): number {
  return items.reduce((sum, d) => sum + d.bytes, 0)
}

// "295 MB", "1.6 GB". Rounded: these are first-visit estimates, not receipts.
export function formatBytes(bytes: number): string {
  if (bytes < 10 * MB) return `${(bytes / MB).toFixed(1)} MB`
  if (bytes < 1000 * MB) return `${Math.round(bytes / MB)} MB`
  return `${(bytes / 1000 / MB).toFixed(1)} GB`
}

