/* Setup: model loading progress */

.load-list {
  list-style: none;
  margin: 4px 0 10px;
  padding: 0;
  display: grid;
  gap: 12px;
}

.load-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 6px;
  font-size: 0.95rem;
}

.load-status {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.load-ready .load-status {
  color: var(--accent);
}

progress {
  appearance: none;
  display: block;
  width: 100%;
  height: 6px;
  border: 0;
  border-radius: var(--radius-pill);
  background: var(--surface-hover);
  overflow: hidden;
}

progress::-webkit-progress-bar {
  background: var(--surface-hover);
  border-radius: var(--radius-pill);
}

progress::-webkit-progress-value {
  background: var(--accent);
  border-radius: var(--radius-pill);
  transition: width var(--ease);
}

progress::-moz-progress-bar {
  background: var(--accent);
  border-radius: var(--radius-pill);
}

.load-note {
  font-size: 0.9rem;
  margin: 0;
}

.start-hint {
  text-align: right;
  font-size: 0.9rem;
  margin: 8px 0 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* A plain notice: neutral, no warning colour (one accent only). */

