      const t0 = performance.now()
      log(`put ${name(key)} start`)
      await cache.put(key, response)
      log(`put ${name(key)} done (${Math.round(performance.now() - t0)} ms)`)
    },
    async delete(key) {
      log(`delete ${name(key)}`)
      return cache.delete(key)
    },
  }
}

