import { BANK, pickQuestions, type Level, type Round, type Track } from '/Users/tanmay/Documents/interview-room/src/interview/bank.ts'

const problems: string[] = []
const ids = new Set<string>()
for (const q of BANK) {
  if (ids.has(q.id)) problems.push(`duplicate id ${q.id}`)
  ids.add(q.id)
  if (q.keyPoints.length < 2) problems.push(`${q.id}: fewer than 2 key points`)
  if (q.followUps.length < 2) problems.push(`${q.id}: fewer than 2 follow-ups`)
  for (const f of q.followUps) if (!f.trim().endsWith('?')) problems.push(`${q.id}: follow-up not a question: ${f}`)
  for (const k of q.keyPoints) for (const m of k.match) if (m !== m.toLowerCase()) problems.push(`${q.id}: match not lowercase: ${m}`)
  if (!q.question.trim().endsWith('?') && !q.question.trim().endsWith('.')) problems.push(`${q.id}: question punctuation`)
}

const levels: Level[] = ['intern', 'junior', 'mid', 'senior']
const tracks: Track[] = ['frontend', 'backend', 'ml']
const rounds: Round[] = ['behavioural', 'technical', 'hr']
const table: Record<string, Record<string, number>> = {}
for (const t of tracks) for (const r of rounds) {
  const row: Record<string, number> = {}
  for (const l of levels) {
    row[l] = BANK.filter((q) => q.round === r && q.levels.includes(l) && (q.tracks.includes('any') || q.tracks.includes(t))).length
    if (row[l] < 3) problems.push(`only ${row[l]} ${r} questions for ${t}/${l}`)
  }
  table[`${t} ${r}`] = row
}

let seed = 1
const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647)
for (const t of tracks) for (const l of levels) {
  const full = pickQuestions({ round: 'full', track: t, level: l, count: 0 }, rand)
  const shape = full.map((q) => q.round[0]).join('')
  if (shape !== 'bbtth') problems.push(`full loop ${t}/${l}: ${shape}`)
  if (new Set(full.map((q) => q.id)).size !== full.length) problems.push(`full loop ${t}/${l}: repeats`)
}

// Key-point matching on the eval fixtures (same padding the engine will use).
const covered = (id: string, answer: string) => {
  const text = ` ${answer.toLowerCase()} `
  return BANK.find((q) => q.id === id)!.keyPoints.map((k) => `${k.label}: ${k.match.some((m) => text.includes(m)) ? 'yes' : 'no'}`)
}
const starGood = 'In my final year project our React app took 9 seconds to load on mobile. I was responsible for the frontend, so I owned fixing it. I profiled it with Lighthouse, found a 2 MB chart library loaded on every page, lazy loaded it and split the routes. Load time dropped to 2.1 seconds and our demo day score went up.'
const we = 'So our team had a really slow dashboard, and we decided to rewrite the data layer. We moved to React Query and we added caching, and we also cleaned up a lot of the components. In the end the dashboard was much faster and the client was happy.'

console.log(`questions: ${BANK.length}`)
console.table(table)
console.log('b-improved, strong STAR answer:', covered('b-improved', starGood))
console.log('b-improved, "we" answer:', covered('b-improved', we))
console.log(problems.length ? `PROBLEMS:\n${problems.join('\n')}` : 'no problems')

