  'jsDelivr avatar': 'https://cdn.jsdelivr.net/gh/927tanmay/react-ai-voice-avatar@avatars-v2/assets/avatars/ananya.glb',
};
const probe = async (url) => { try { const r = await fetch(url, { headers: { Range: 'bytes=0-2047' } }); const b = await r.arrayBuffer(); return `${r.status} ${b.byteLength}B` } catch (e) { return 'BLOCKED: ' + e.message } };
const page = {};
for (const [k, u] of Object.entries(targets)) page[k] = await probe(u);
const src = `onmessage = async (e) => { const out = {}; for (const [k, u] of Object.entries(e.data)) { try { const r = await fetch(u, { headers: { Range: 'bytes=0-2047' } }); const b = await r.arrayBuffer(); out[k] = r.status + ' ' + b.byteLength + 'B' } catch (err) { out[k] = 'BLOCKED: ' + err.message } } postMessage({ isolated: self.crossOriginIsolated, out }) }`;
const w = new Worker(URL.createObjectURL(new Blob([src], { type: 'text/javascript' })));
const worker = await new Promise((res) => { w.onmessage = (e) => res(e.data); w.onerror = (e) => res('worker error: ' + e.message); w.postMessage(targets); setTimeout(() => res('timeout'), 30000) });
w.terminate();
({ page, worker })

