"""Replace one email address in Entire's checkpoint refs (refs/entire/*) only.

For every commit reachable from those refs (oldest first): rewrite any blob
containing the address, recompute content_hash.txt (sha256 of full.jsonl) when
full.jsonl changed, rebuild the trees, recreate the commit with the same
author, committer, dates and message, and move the ref. Nothing else is
touched: refs/heads/* and their commits are never read or written.
"""
import hashlib
import subprocess
import sys

EMAIL = ('007dev' + 'lok' + '@' + 'gmail' + '.com').encode()
REPL = b'[REDACTED_EMAIL]'


def git(*args, data=None):
    return subprocess.run(['git', *args], input=data, capture_output=True, check=True).stdout


def write_blob(data):
    return git('hash-object', '-w', '--stdin', data=data).decode().strip()


stats = {'blobs': 0, 'hashes': 0, 'commits': 0}
tree_map = {}


def rewrite_tree(sha):
    if sha in tree_map:
        return tree_map[sha]
    items = []
    for line in git('ls-tree', '-z', sha).split(b'\0'):
        if not line:
            continue
        meta, path = line.split(b'\t', 1)
        mode, typ, obj = meta.split()
        items.append([mode, typ, obj.decode(), path])

    changed = False
    old_full = new_full = None
    for it in items:
        mode, typ, obj, path = it
        if typ == b'tree':
            new = rewrite_tree(obj)
        elif typ == b'blob':
            data = git('cat-file', 'blob', obj)
            new = obj
            if EMAIL in data:
                fixed = data.replace(EMAIL, REPL)
                new = write_blob(fixed)
                stats['blobs'] += 1
                if path == b'full.jsonl':
                    old_full, new_full = data, fixed
        else:
            new = obj
        if new != obj:
            it[2] = new
            changed = True

    if new_full is not None:
        for it in items:
            if it[3] == b'content_hash.txt':
                stored = git('cat-file', 'blob', it[2]).decode().strip()
                expected = 'sha256:' + hashlib.sha256(old_full).hexdigest()
                if stored != expected:
                    sys.exit(f'content_hash.txt in tree {sha} is not the hash of full.jsonl; stopping')
                it[2] = write_blob(('sha256:' + hashlib.sha256(new_full).hexdigest()).encode())
                stats['hashes'] += 1

    result = sha
    if changed:
        listing = b''.join(m + b' ' + t + b' ' + o.encode() + b'\t' + p + b'\0' for m, t, o, p in items)
        result = git('mktree', '-z', data=listing).decode().strip()
    tree_map[sha] = result
    return result


commit_map = {}


def rewrite_commit(sha):
    if sha in commit_map:
        return commit_map[sha]
    raw = git('cat-file', 'commit', sha)
    header, _, message = raw.partition(b'\n\n')
    lines = []
    for line in header.split(b'\n'):
        if line.startswith(b'tree '):
            line = b'tree ' + rewrite_tree(line[5:].decode()).encode()
        elif line.startswith(b'parent '):
            line = b'parent ' + rewrite_commit(line[7:].decode()).encode()
        elif line.startswith(b'gpgsig'):
            sys.exit(f'commit {sha} is signed; stopping')
        lines.append(line)
    new_raw = b'\n'.join(lines) + b'\n\n' + message
    new = git('hash-object', '-t', 'commit', '-w', '--stdin', data=new_raw).decode().strip()
    if new != sha:
        stats['commits'] += 1
    commit_map[sha] = new
    return new


refs = git('for-each-ref', '--format=%(refname) %(objectname)', 'refs/entire/').decode().split('\n')
moved = 0
for line in filter(None, refs):
    ref, old = line.split()
    new = rewrite_commit(old)
    if new != old:
        git('update-ref', '-m', 'redact email from checkpoint', ref, new, old)
        moved += 1
print(f"refs: {len(list(filter(None, refs)))}, moved: {moved}, commits rewritten: {stats['commits']}, "
      f"blobs rewritten: {stats['blobs']}, content hashes recomputed: {stats['hashes']}")

