// ---------------------------------------------------------------- engine
type Timer = { fn: () => void; at: number; id: number }
function harness(write: EngineDeps['write']) {
  let now = 0
  let nextId = 1
  let timers: Timer[] = []
  const spoken: string[] = []
  const deps: EngineDeps = {
    speak: (t) => spoken.push(t),
    write,
    now: () => now,
    setTimer: (fn, ms) => {
      const t = { fn, at: now + ms, id: nextId++ }
      timers.push(t)
      return t.id
    },
    clearTimer: (id) => (timers = timers.filter((t) => t.id !== id)),
  }
  const advance = async (ms: number) => {
    now += ms
    for (const t of timers.filter((t) => t.at <= now)) {
      timers = timers.filter((x) => x !== t)
      t.fn()
    }
    await new Promise((r) => setTimeout(r, 0))
  }
  return { deps, spoken, advance }
}

const plan = { questions: [q('b-improved'), q('fe-useeffect')], track: 'frontend' as const, level: 'junior' as const, interviewer: 'Ananya', mood: 'friendly' as const }

{
  const h = harness(async () => 'Okay. What did you change yourself?')
  const e = new InterviewEngine(plan, h.deps)
  e.start()
  check('engine: greets with small talk', h.spoken[0]?.includes("I'm Ananya") && e.snapshot().phase === 'small-talk')
  e.heard('Pretty good, thanks.')
  await h.advance(4000)
  check('engine: 4 s of quiet does not end an answer', e.snapshot().phase === 'small-talk')
  await h.advance(1500)
  check('engine: long pause moves to the first question', e.snapshot().phase === 'answering' && h.spoken.at(-1)!.includes(plan.questions[0].question), h.spoken.at(-1))

  // An answer across three pauses, with the candidate resuming each time.
  check('engine: package gets an empty reply', e.heard('So our team had a really slow dashboard,') === '')
  await h.advance(3000)
  e.userStartedSpeaking()
  await h.advance(4000)
  e.heard('and we decided to rewrite the data layer. We moved to React Query and we added caching,')
  await h.advance(3000)
  e.userStartedSpeaking()
  await h.advance(6000)
  e.heard('and in the end the dashboard was much faster and the client was happy.')
  check('engine: thinking pauses kept it one answer', e.snapshot().phase === 'answering' && e.snapshot().currentAnswer.split(' ').length > 30)
  await h.advance(5000)
  const fu = e.snapshot().records[0].exchanges.at(-1)!
  check('engine: Gemma follow-up after the long pause', e.snapshot().phase === 'follow-up' && fu.byGemma === true && fu.angle?.kind === 'ownership', `${fu.angle?.kind}: ${fu.said}`)
// ---------------------------------------------------------------- recovery
{
  const h = harness(async () => 'What did you do yourself?')
  const e = new InterviewEngine({ ...plan, questions: [q('b-pressure'), q('fe-useeffect')] }, h.deps)
  e.start()
  e.heard('Good, thanks.')
  e.done()
  await h.advance(0)
  const first = h.spoken.at(-1)!

  e.heard('Can you repeat the question?')
  check('recovery: "repeat" says the bank question again', h.spoken.at(-1) === q('b-pressure').question && e.snapshot().currentAnswer === '', h.spoken.at(-1))

  e.heard('What do you mean?')
  check('recovery: "what do you mean" rephrases from the intent', h.spoken.at(-1)!.startsWith("Let me put it another way. I'd like to hear how you stay methodical"), h.spoken.at(-1))

  e.heard('Thank you.')
  check('recovery: garbled at the start -> "didn\'t catch that"', h.spoken.at(-1)!.startsWith("Sorry, I didn't catch that"))

  e.interviewerFinished()
  await h.advance(11000)
  check('recovery: no nudge before 12 s of silence', !h.spoken.at(-1)!.startsWith('Take your time'))
  await h.advance(1000)
  check('recovery: nudge after 12 s of silence', h.spoken.at(-1) === 'Take your time. Want me to repeat the question?')
  e.interviewerFinished()
  await h.advance(13000)
  check('recovery: moves on after 25 s and marks it silent', e.snapshot().records[0].outcome === 'silent' && e.snapshot().questionIndex === 1, h.spoken.at(-1))

  e.heard('What do you mean?')
  check('recovery: technical rephrase does not give the answer away', h.spoken.at(-1)!.startsWith('Sure. Just explain it the way you would to a teammate.'), h.spoken.at(-1))

  e.heard("I don't know.")
  check('recovery: first "I don\'t know" gets a nudge', h.spoken.at(-1)!.startsWith("That's okay. Take a guess"))
  e.heard('No idea, sorry.')
  check('recovery: second "I don\'t know" moves on', e.snapshot().records[1].outcome === 'dont-know' && e.snapshot().phase === 'candidate-questions')
}

{
  // Silence while the candidate is mid-answer does not nudge; talking resets.
  const h = harness(async () => null)
  const e = new InterviewEngine({ ...plan, questions: [q('b-pressure')] }, h.deps)
  e.start()
  e.heard('Fine.')
  e.done()
  await h.advance(0)
  e.interviewerFinished()
  await h.advance(8000)
  e.userStartedSpeaking()
  await h.advance(10000)
  check('recovery: starting to talk cancels the silence nudge', !h.spoken.at(-1)!.startsWith('Take your time'))
}

{
  // Pause by voice, by button, hidden tab; resume by voice or button.
  const h = harness(async () => null)
  const e = new InterviewEngine({ ...plan, questions: [q('b-pressure')] }, h.deps)
  e.start()
  e.heard('Fine.')
  e.done()
  await h.advance(0)
  e.heard('So there was this release where the build broke,')
  e.heard('Can we pause for a minute?')
  check('pause: by voice, says so and keeps the answer so far', e.snapshot().paused === 'asked' && h.spoken.at(-1)!.startsWith('Sure, take your time') && e.snapshot().currentAnswer.includes('build broke'))
  await h.advance(60000)
  check('pause: no long-pause timer while paused', e.snapshot().phase === 'answering')
  e.heard('and some other words while paused')
  check('pause: speech while paused is not added', !e.snapshot().currentAnswer.includes('other words'))
  e.heard("Okay, I'm ready.")
  check('pause: "I\'m ready" resumes', e.snapshot().paused === null && h.spoken.at(-1) === "Okay, let's carry on.")
  e.pause('hidden')
  check('pause: hidden tab pauses silently', e.snapshot().paused === 'hidden' && h.spoken.at(-1) === "Okay, let's carry on.")
  e.resume()
  e.heard('and I fixed it by rolling back the dependency.')
  await h.advance(0)
  for (let i = 0; i < 3; i++) {
    e.heard('I fixed a bug once that was urgent.')
    e.done()
    await h.advance(0)
    e.heard('That is all I remember about it.')
    e.done()
    await h.advance(0)
  }
  check('gemma: stops asking after 2 failures', calls === 2, `calls=${calls}`)
  check('gemma: noted for the report', e.snapshot().notes.length === 1, e.snapshot().notes[0])
  check('gemma: interview still reached the end', e.snapshot().phase === 'candidate-questions')
}

