{
  const phrases = (t: string) => findFillers(t).map((f) => f.phrase).join(', ')
  const t1 = 'So, you know, it was basically, like, really slow. Do you know what kind of database it was? I mean, it was kind of old.'
  check('fillers: the five kinds, not the real meanings', phrases(t1) === 'you know, basically, like, I mean, kind of', phrases(t1))
  const hit = findFillers(t1)[0]
  check('fillers: offsets point at the words', t1.slice(hit.start, hit.end) === 'you know')
  check('fillers: "like" without a comma is not counted', phrases('We used things like React and Vue.') === '')
  check('fillers: "would like," is not counted', phrases('I would like, if possible, to explain.') === '')
  check('fillers: "a kind of cache" is not counted', phrases('It is a kind of cache that sits in front.') === '')
  check('fillers: "what I mean is" is not counted', phrases('What I mean is the cache was stale.') === '')
  check('fillers: curly apostrophe in "don’t you know"', phrases('Why don’t you know the answer?') === '')
  check('fillers: case does not matter', phrases('Basically we, You know, shipped it.') === 'basically, you know')

  const pr = countPronouns('I built it, we shipped it, my team and I, our users. I mean, it worked for us. I’m happy.')
  check('pronouns: I-words and we-words, "I mean" left out', pr.i === 4 && pr.we === 3, JSON.stringify(pr))

  const nums = findNumbers('Load time dropped from 9 seconds to 2.1 seconds, about 40% faster, for two hundred thousand users back in 2023, with one thousand requests a minute and $5 a month.').map((s) => s.text)
  check('numbers: digits, units, percent, words, money; not a year', JSON.stringify(nums) === JSON.stringify(['9 seconds', '2.1 seconds', '40%', 'two hundred thousand users', 'one thousand requests', '$5']), JSON.stringify(nums))
  check('numbers: "one of the" and "often" are not numbers', findNumbers('One of the services often failed.').length === 0)
  check('numbers: "1,000 users" and "40 percent"', JSON.stringify(findNumbers('About 1,000 users, 40 percent of them.').map((s) => s.text)) === '["1,000 users","40 percent"]')

  // Timing: question ends at 1000; 3 stretches; a 4 s gap after the first.
  const words = (n: number) => Array.from({ length: n }, (_, i) => `w${i}`).join(' ')
  const ex = (parts: AnswerPart[], askedEndedAt?: number): Exchange => ({ kind: 'question', said: 'Q', parts, askedAt: 0, askedEndedAt })
  const timed = ex(
    [
      { text: words(20), speechMs: 8000, at: 0, startedAt: 2500, endedAt: 10500 },
      { text: words(30), speechMs: 12000, at: 0, startedAt: 14500, endedAt: 26500 },
      { text: words(10), speechMs: 4000, at: 0, startedAt: 28500, endedAt: 32500 },
    ],
    1000,
  )
  const tm = measureTiming(timed)
  check('timing: time to first word', tm.firstWordMs === 1500 && !tm.talkedOver)
  check('timing: only gaps over 3 s count', tm.longGaps.length === 1 && tm.longGaps[0].ms === 4000 && tm.longGaps[0].afterPart === 0, JSON.stringify(tm.longGaps))
  check('timing: gap offset is where the next stretch starts', answerText(timed).slice(tm.longGaps[0].at).startsWith('w0 w1') && tm.longGaps[0].at === words(20).length + 1)
  check('timing: duration first word to last', tm.durationMs === 30000)
  check('timing: wpm from speech time (60 words in 24 s = 150)', tm.wpm === 150 && paceBand(tm.wpm) === 'in-band')
  check('timing: pace bands', paceBand(119) === 'slow' && paceBand(161) === 'fast' && paceBand(null) === null)

  const over = overTargetAt(timed, 20000) // limit at 22500: 8 s into the 12 s second stretch -> word 20 of 30
  const offset2 = words(20).length + 1
  check('over target: inside a stretch, placed by word share', over === offset2 + words(30).indexOf('w20'), `${over}`)
  check('over target: in a gap, at the next stretch', overTargetAt(timed, 11000) === offset2)
  check('over target: within target, none', overTargetAt(timed, 31000) === null)

  const early = measureTiming(ex([{ text: words(5), speechMs: 2000, at: 0, startedAt: 500, endedAt: 2500 }], 1000))
  check('timing: talking over the question shows as 0 and flagged', early.firstWordMs === 0 && early.talkedOver)
  check('timing: too little speech, no wpm', early.wpm === null)
  const untimed = measureTiming(ex([{ text: words(40), at: 0 }]))
  check('timing: no detector times -> not measured, not guessed', untimed.firstWordMs === null && untimed.durationMs === null && untimed.wpm === null && untimed.longGaps.length === 0)
  check('over target: no detector times -> none', overTargetAt(ex([{ text: words(40), at: 0 }]), 1000) === null)

  // Questions: answered with a follow-up, skipped, ended before a word.
  const rec = (id: string, outcome: QuestionRecord['outcome'], exchanges: Exchange[]): QuestionRecord => ({ question: q(id), exchanges, outcome, startedAt: 0 })
  const fuEx: Exchange = { ...ex([{ text: 'I would add a cleanup, basically.', speechMs: 3000, at: 0 }]), kind: 'follow-up', said: 'What about cleanup?' }
  const records = [
    rec('fe-useeffect', 'answered', [timed, fuEx]),
    rec('b-pressure', 'skipped', [ex([])]),
    rec('b-improved', 'answered', [ex([])]),
    rec('b-conflict', 'dont-know', [ex([{ text: "I don't know.", at: 0 }])]),
  ]
  const m = measureInterview(records, 20000)
  check('question: answered is measured, with the follow-up reply', m.questions[0].status === 'answered' && m.questions[0].answer?.words === 60 && m.questions[0].followUp?.reply?.fillers.length === 1)
  check('question: over target by 10 s', m.questions[0].overTargetMs === 10000 && m.questions[0].overTargetAt !== null)
  check('question: skipped / ended early / don\'t know are not measured', m.questions[1].status === 'skipped' && m.questions[2].status === 'empty' && m.questions[3].status === 'dont-know' && m.questions.slice(1).every((x) => x.answer === null))
  check('interview: totals', m.answered === 1 && m.words === 66 && m.fillers[0]?.phrase === 'basically' && m.longGaps === 1 && m.overTarget === 1 && m.firstWordMs.join() === '1500', JSON.stringify({ ...m, questions: undefined }))
}

console.log(failures ? `\n${failures} FAILED` : '\nall passed')

