import { lazy, Suspense, useReducer } from 'react'
import { appReducer, initialState, isVoiceMounted } from './app/state'
import { useDeviceCheck } from './app/useDeviceCheck'
import { PrivacyNote } from './components/PrivacyNote'
import { VoiceHost } from './voice/VoiceHost'
import { loadReducer } from './voice/loading'
import { voiceControls } from './voice/voiceStore'
import { Home } from './screens/Home'
import { Interview } from './screens/Interview'
import { Report } from './screens/Report'
import { Setup } from './screens/Setup'

// Dev-only panels (`?dev=gemma`, `?dev=setup`, `?dev=room`, `?dev=avatar`); dropped from production.
const GemmaTest = import.meta.env.DEV ? lazy(() => import('./dev/GemmaTest')) : null
const SetupPreview = import.meta.env.DEV ? lazy(() => import('./dev/SetupPreview')) : null
const RoomPreview = import.meta.env.DEV ? lazy(() => import('./dev/RoomPreview')) : null
const AvatarPreview = import.meta.env.DEV ? lazy(() => import('./dev/AvatarPreview')) : null
const devPanel = import.meta.env.DEV ? new URLSearchParams(location.search).get('dev') : null

function App() {
  const [state, dispatch] = useReducer(appReducer, initialState)
  const [load, dispatchLoad] = useReducer(loadReducer, {})
  const device = useDeviceCheck()

  const FullPanel = devPanel === 'room' ? RoomPreview : devPanel === 'avatar' ? AvatarPreview : null
  if (FullPanel) {
    return (
      <Suspense fallback={null}>
        <FullPanel />
      </Suspense>
    )
  }
  const DevPanel = devPanel === 'gemma' ? GemmaTest : devPanel === 'setup' ? SetupPreview : null
  if (DevPanel) {
    return (
      <div className="app">
        <main>
          <Suspense fallback={null}>
            <DevPanel />
          </Suspense>
        </main>
      </div>
    )
  }

  return (
    <div className={`app app--${state.screen}`}>
      <main>
        {state.screen === 'home' && (
          <Home device={device} onChooseMode={(mode) => dispatch({ type: 'chooseMode', mode })} />
        )}
        {state.screen === 'setup' && state.mode && (
          <Setup
            mode={state.mode}
            display={state.display}
            settings={state.settings}
            load={load}
            onChooseDisplay={(display, interviewer) => dispatch({ type: 'chooseDisplay', display, interviewer })}
            onSettingsChange={(patch) => dispatch({ type: 'updateSettings', patch })}
            onStart={() => {
              // Opened inside the click: the browser needs a user gesture for
              // the microphone and for audio playback.
              void voiceControls()?.startListening()
              dispatch({ type: 'startInterview' })
            }}
            onBack={() => dispatch({ type: 'goHome' })}
          />
        )}
        {state.screen === 'interview' && state.display && (
          <Interview
            display={state.display}
            settings={state.settings}
            onEnd={() => dispatch({ type: 'finishInterview' })}
          />
        )}
        {state.screen === 'report' && (
          <Report
            onPracticeAgain={() => dispatch({ type: 'practiceAgain' })}
            onHome={() => dispatch({ type: 'goHome' })}
          />
        )}
      </main>

      {/* Same position in the tree on setup and interview, so changing screen
          never remounts the engine (and never kills its workers). */}
      {isVoiceMounted(state) && (
        <VoiceHost
          display={state.display}
          mode={state.mode}
          interviewer={state.settings.interviewer}
          visible={state.screen === 'interview'}
          onLoad={dispatchLoad}
        />
      )}

      <footer>
        <PrivacyNote />
      </footer>
    </div>
  )
}

export default App
import { DEFAULT_SETTINGS, normalise, type InterviewerId, type InterviewSettings } from '../interview/settings'

// App-level state: which screen is showing and what the candidate chose.
// Screens are switched here rather than by URL; there is nothing to link to
// inside an interview.

export type Mode = 'light' | 'heavy'
// How the interviewer appears. Same interview either way; only the display
// changes. 'video' shows the 3D avatar, 'phone' is voice only.
export type Display = 'video' | 'phone'
export type Screen = 'home' | 'setup' | 'interview' | 'report'

export type AppState = {
  screen: Screen
  mode: Mode | null
  // Null until picked on the setup screen. Picking it (with the interviewer,
  // whose avatar and voice load with it) starts loading the models, and it
  // cannot change after that (UX.md: downloads).
  display: Display | null
  settings: InterviewSettings
}

export type AppAction =
  | { type: 'chooseMode'; mode: Mode }
  | { type: 'chooseDisplay'; display: Display; interviewer: InterviewerId }
  | { type: 'updateSettings'; patch: Partial<InterviewSettings> }
  | { type: 'startInterview' }
  | { type: 'finishInterview' }
  | { type: 'practiceAgain' }
  | { type: 'goHome' }

export const initialState: AppState = { screen: 'home', mode: null, display: null, settings: DEFAULT_SETTINGS }

export function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'chooseMode':
      return { ...state, mode: action.mode, display: null, screen: 'setup' }
    case 'chooseDisplay':
      return state.display
        ? state
        : { ...state, display: action.display, settings: { ...state.settings, interviewer: action.interviewer } }
    case 'updateSettings': {
      // The interviewer is locked once the models start loading.
      const { interviewer: _locked, ...patch } = action.patch
      const next = state.display ? patch : action.patch
      return { ...state, settings: normalise({ ...state.settings, ...next }) }
    }
    case 'startInterview':
      return state.mode && state.display ? { ...state, screen: 'interview' } : state
    case 'finishInterview':
      return { ...state, screen: 'report' }
    case 'practiceAgain':
      return { ...state, display: null, screen: 'setup' }
    case 'goHome':
      return { ...state, display: null, screen: 'home' }
  }
}

// The voice engine (react-ai-voice-avatar) owns its workers and kills them on
// unmount, so it is mounted once, from the display choice until the interview
// ends, and the screens change around it.
export function isVoiceMounted(state: AppState): state is AppState & { display: Display; mode: Mode } {
  return (
    state.display !== null &&
    state.mode !== null &&
    (state.screen === 'setup' || state.screen === 'interview')
  )
}
