.screen {
  padding: 28px 28px 24px;
  animation: screen-in var(--ease);
}

@media (max-width: 520px) {
  .screen {
    padding: 20px 16px;
  }

  .screen .panel {
    padding: 14px;
  }
}

@keyframes screen-in {
  from {
    opacity: 0;
  }
}

/* Type */

h1 {
  font-size: 1.85rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0 0 12px;
}

h2,
legend {
  font-size: 1.05rem;
  font-weight: 600;
  margin: 0 0 6px;
  padding: 0;
}

h1:focus,
h2:focus {
  outline: none;
}

p {
  margin: 0 0 8px;
}

.lede {
  color: var(--muted);
  font-size: 1.08rem;
  margin-bottom: 24px;
}

.muted {
  color: var(--muted);
}

.placeholder {
  color: var(--muted);
  font-style: italic;
}

.privacy-note {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0;
}

/* Plain surfaces inside the glass panel: no blur. */

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px 18px;
  margin: 0 0 14px;
}

/* Controls */

button {
  font: inherit;
  font-weight: 500;
  border-radius: var(--radius-md);
  padding: 10px 18px;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  transition:
    background-color var(--ease),
    border-color var(--ease),
    opacity var(--ease);
}

button:hover {
  background: var(--surface-hover);
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}

button.primary:hover {
  opacity: 0.9;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

input[type='radio'] {
  accent-color: var(--accent);
  width: 18px;
  height: 18px;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
  margin-top: 18px;
}

/* Home: mode choice */

.mode-options {
  display: grid;
  gap: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  position: relative;
  cursor: pointer;
}

/* The radio stays in the page for keyboard and screen readers; the chip is
   its visible face. */
.chip input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: inherit;
}

.chip span {
  display: inline-block;
  padding: 7px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--surface);
  transition:
    background-color var(--ease),
    border-color var(--ease);
}

.chip:hover span {
  background: var(--surface-hover);
}

.chip input:checked + span {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--text);
}

.chip input:focus-visible + span {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.chip-disabled {
  cursor: not-allowed;
}

.chip-disabled span {
  border-style: dashed;
  color: var(--muted);
}

.chip-hint {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0;
}

  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Dev-only session log */

.session-log summary {
  cursor: pointer;
  font-weight: 600;
}

.session-log pre {
  max-height: 360px;
  overflow: auto;
  font-size: 0.8rem;
  background: var(--surface);
  border-radius: var(--radius-sm);
  padding: 12px;
  margin: 12px 0 0;
  white-space: pre-wrap;
}

/* A plain notice: neutral, no warning colour (one accent only). */
.notice {
  border-left: 3px solid var(--text);
  padding: 2px 0 2px 14px;
}
}

.said {
  color: var(--muted);
}

.state {
  display: inline-block;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: var(--radius-pill);
  padding: 3px 14px;
  margin-bottom: 12px;
}

.label {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin: 18px 0 4px;
}

.question {
  font-size: 1.25rem;
  line-height: 1.45;
}

.interview-controls {
  justify-content: flex-start;
}

button.quiet {
  margin-left: auto;
  background: transparent;
  border-color: transparent;
  color: var(--muted);
}

button.quiet:hover {
  color: var(--text);
  background: var(--surface);
}

/* Interview room: state, progress, timer */

.room-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px 16px;
