  const top = m.fillers.slice(0, 2).map((f) => `"${f.phrase}" ${times(f.count)}`)
  const byAnswer = m.questions
    .map((q) => ({ id: q.questionId, n: (q.answer?.fillers.length ?? 0) + (q.followUp?.reply?.fillers.length ?? 0) }))
