// ---------------------------------------------------------------- focus rules (report step 6)
{
  // One answer, one stretch: `secs` long, spoken at `wpm`.
  const said = (text: string, secs: number, kind: Exchange['kind'] = 'question'): Exchange => {
    const words = text.split(/\s+/).length
    return { kind, said: 'Q', askedAt: 0, askedEndedAt: 0, parts: [{ text, at: 0, startedAt: 1000, endedAt: 1000 + secs * 1000, speechMs: secs * 1000 }], ...(words ? {} : {}) }
  }
  const record = (id: string, ...exchanges: Exchange[]): QuestionRecord => ({ question: q(id), exchanges, outcome: 'answered', startedAt: 0 })
  const report = (records: QuestionRecord[], review: InterviewReport['review'], answerMinutes = 1): InterviewReport => ({
    id: 't', version: 1, createdAt: 0, mode: 'light', display: 'phone', settings: { ...DEFAULT_SETTINGS, answerMinutes },
    records, smallTalk: null, candidateQuestions: null, notes: [], review, reviewState: 'done',
  })
  const weStory = 'So we had a slow dashboard and we looked into it as a team. We added caching and we split the bundle, and our users were much happier after that. I helped a bit.'
  const plain = 'There was an outage in production during a release and I was on call. I checked the logs, found a bad config change, rolled it back and wrote a checklist so it would not happen again.'

  // A: every rule has something to say.
  const a = report(
    [
      record('b-improved', said(weStory, 80)),
      record('b-feedback', said('My lead told me my pull requests were too big. I asked what size worked for the team and started splitting them up.', 40)),
      record('b-pressure', said(plain, 100)),
    ],
    {
      'b-improved': { feel: 'good', marks: ['covered', 'covered', 'missed', 'missed'] },
      'b-feedback': { feel: 'okay', marks: ['covered', 'covered', 'partly', 'missed'] },
      'b-pressure': { feel: 'rough', marks: ['covered', 'covered', 'covered', 'covered', 'missed'] },
    },
  )
  const fa = pickFocus(a)
  check('focus: three items, in rule order', fa.map((f) => f.rule).join() === 'missed-tag,felt-good-missed,over-target', fa.map((f) => f.rule).join())
  check('focus: most-missed kind of point, from marks', fa[0].title === 'End with the result' && fa[0].detail === 'You marked the result as missed in 2 of 3 answers where it came up.' && fa[0].source === 'marks' && fa[0].questionIds.join() === 'b-improved,b-feedback', fa[0].detail)
  check('focus: felt good but mostly missed', fa[1].questionIds.join() === 'b-improved' && fa[1].detail.includes('felt good, but you marked 2 of 4 points as missed'), fa[1].detail)
  check('focus: furthest over target, plain comparison', fa[2].questionIds[0] === 'b-pressure' && fa[2].detail.includes('ran 1 min 40 s; the target you set was 1 min. 1 other answer also went over.'), fa[2].detail)
  check('focus: each says where it came from', fa.every((f) => f.from.length > 0))

  const da = findDisagreements(a)
  check('disagree: result covered with no number', da.some((d) => d.rule === 'result-no-number' && d.questionId === 'b-pressure'), JSON.stringify(da.map((d) => d.rule + ':' + d.questionId)))
  check('disagree: own role covered, "we" far more than "I"', da.some((d) => d.rule === 'role-we' && d.questionId === 'b-improved' && d.detail.includes('"we" 7 times and "I" 1 time')), da.find((d) => d.rule === 'role-we')?.detail)
  check('disagree: nothing else', da.length === 2)

  // A result with a number is not questioned; a follow-up reply counts too.
  const withNumber = report([record('b-pressure', said(plain, 40), said('It was fixed in 20 minutes.', 3, 'follow-up'))], { 'b-pressure': { feel: 'good', marks: ['covered', 'covered', 'covered', 'covered', 'covered'] } })
  check('disagree: a number in the follow-up reply counts', findDisagreements(withNumber).length === 0)

  // B: review skipped, so numbers only: fillers and a fast pace.
  const fast = 'So basically, you know, I basically built the page and, like, basically it worked, you know, and I mean it was kind of fine and basically we shipped it on time, you know.'
  const b = report([record('fe-useeffect', said(fast, 10)), record('fe-state', said(fast, 11))], {})
  const fb = pickFocus({ ...b, reviewState: 'skipped' })
  check('focus: no marks -> from the numbers only', fb.map((f) => f.rule).join() === 'fillers,pace' && fb.every((f) => f.source === 'measured'), fb.map((f) => f.rule).join())
  check('focus: fillers name the top phrases', fb[0].detail.startsWith('You said "basically" 10 times and "you know" 6 times'), fb[0].detail)
  check('focus: pace says which way', fb[1].title === 'Slow down a little' && fb[1].detail.startsWith('2 of 2 answers were above 160'), fb[1].detail)

  // C: nothing stands out.
  const c = report([record('b-pressure', said(plain, 40))], { 'b-pressure': { feel: 'okay', marks: ['covered', 'covered', 'covered', 'partly', 'covered'] } }, 2)
  check('focus: nothing stands out -> no items', pickFocus(c).length === 0, pickFocus(c).map((f) => f.rule).join())
  check('focus: one partly is not "missed"', !pickFocus(c).some((f) => f.rule === 'missed-tag'))

  // Unmarked points are not counted as missed.
  const unmarked = report([record('b-improved', said(weStory, 40))], { 'b-improved': { feel: 'good', marks: [null, null, null, 'covered'] } }, 2)
  check('focus: unmarked points are not missed', pickFocus(unmarked).length === 0)

  check('format: durations', formatDuration(45_000) === '45 s' && formatDuration(120_000) === '2 min' && formatDuration(220_400) === '3 min 40 s')
}

