python3 - <<'EOF'
p='src/report/focus.ts'
s=open(p).read()
s=s.replace("""// The smallest overrun worth a focus item.
const OVER_MIN_MS = 15_000""","""// The smallest overrun worth a focus item: 15% of the target, at least 10 s.
const OVER_SHARE = 0.15
const OVER_MIN_MS = 10_000""")
s=s.replace("""//   1. the kind of point they marked missed most often ("you left out the
//      result in 3 of 4 answers"),""","""//   1. the kind of point they marked missed most often ("you left out the
//      result in 3 of 4 answers"); ties go to the one missed in the larger
//      share of the answers where it came up,""")
s=s.replace("""// 1. The kind of point missed most often: missed in at least half of the
//    answers where it came up. Ties go to the one that came up most.""","""// 1. The kind of point missed most often: missed in at least half of the
//    answers where it came up. Ties go to the larger share missed, then to
//    the one that came up most.""")
s=s.replace("""    .sort((a, b) => b.missed.length - a.missed.length || b.answers.length - a.answers.length)[0]""","""    .sort(
      (a, b) =>
        b.missed.length - a.missed.length ||
        b.missed.length / b.answers.length - a.missed.length / a.answers.length ||
        b.answers.length - a.answers.length,
    )[0]""")
