            : 'none counted'}
        </dd>
      </div>
      <div>
        <dt>"I" and "we"</dt>
        <dd>
          "I" {times(answer.pronouns.i)}, "we" {times(answer.pronouns.we)}
        </dd>
      </div>
      <div>
        <dt>Numbers</dt>
        <dd>{answer.numbers.length ? answer.numbers.map((n) => n.text).join(', ') : 'none heard'}</dd>
      </div>
    </dl>
  )
}

